const r = $json || {};
const asText = v => {
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join('\n');
  if (v && typeof v === 'object') return asText(v.text ?? v.content ?? v.output_text ?? '');
  return '';
};
const candidates = [
  r.content,  // Claude/Anthropic: content: [{ type: 'text', text: '...' }]
  r.choices?.[0]?.message?.content,
  r.choices?.[0]?.text,
  r.candidates?.[0]?.content?.parts,
  r.candidates?.[0]?.output,
  r.output_text,
  r.output?.[0]?.content,
  r.response,
  r.data?.choices?.[0]?.message?.content,
  r.data?.candidates?.[0]?.content?.parts
];
const text = candidates.map(asText).find(v => String(v || '').trim().length >= 20) || '';
const response = String(text).replace(/^\s*```(?:markdown|text)?\s*/i,'').replace(/\s*```\s*$/,'').trim();
return [{json:{ok:response.length >= 20,response,provider:'Claude',error:response ? '' : JSON.stringify(r.error || r)}}];

const r=$json||{};
const mode=$('02 – BUCHART ERKENNEN').first().json.produktionsmodus;

function collect(v, out=[], depth=0) {
  if (v == null || depth > 8) return out;
  if (typeof v === 'string') {
    const s=v.trim();
    if (s) out.push(s);
    return out;
  }
  if (Array.isArray(v)) {
    for (const x of v) collect(x,out,depth+1);
    return out;
  }
  if (typeof v === 'object') {
    const preferred=['text','content','output_text','response','body','data','parts','message','candidates','choices'];
    for (const k of preferred) if (k in v) collect(v[k],out,depth+1);
    return out;
  }
  return out;
}

const texts=collect(r);
let response=texts
  .filter(t => !/^\{?"?(error|statusCode|httpCode)"?\s*:/i.test(t))
  .sort((a,b)=>b.length-a.length)[0] || '';

response=response
  .replace(/^\s*```(?:markdown|text|md)?\s*/i,'')
  .replace(/\s*```\s*$/,'')
  .trim();

const pageCount=(response.match(/^##\s*Seite\s+\d+/gmi)||[]).length;
const chapterCount=(response.match(/^##\s+/gmi)||[]).length;
const wordCount=response?response.split(/\s+/).filter(Boolean).length:0;

let ok;
if(mode==='VISUELL'){
  ok=pageCount>=5 || wordCount>=180 || response.length>=1200;
}else{
  ok=chapterCount>=2 || wordCount>=1200 || response.length>=8000;
}

// Wichtig: Diagnose immer mitführen; keine Informationen verlieren.
let errorMessage='';
if(!response){
  errorMessage = String(
    r.error?.message ||
    r.error?.error?.message ||
    (typeof r.error === 'string' ? r.error : '') ||
    r.message ||
    r.statusMessage ||
    ''
  );
  if (!errorMessage) {
    // Fallback: rohe Antwort mitschicken, damit der echte API-Fehler
    // (z. B. Anthropic/Gemini invalid_request_error) sichtbar bleibt,
    // statt in einer leeren apiError-Meldung verloren zu gehen.
    try { errorMessage = JSON.stringify(r.error || r).slice(0, 1500); } catch (e) {}
  }
}

return [{
  json:{
    ok,
    response,
    produktionsmodus:mode,
    pageCount,
    chapterCount,
    wordCount,
    rawHadContent:response.length>0,
    httpStatus:r.statusCode || r.status || r.httpCode || null,
    apiError:errorMessage,
    rawKeys:Object.keys(r)
  }
}];

const current = $json || {};
let d = $json || {};
try { d = Object.assign({}, $('02 – BUCHART ERKENNEN').first().json, $json); } catch (e) { d = $json || {}; }

function textOf(obj) {
  if (!obj) return '';
  if (typeof obj.response === 'string' && obj.response.trim()) return obj.response.trim();
  if (typeof obj.text === 'string' && obj.text.trim()) return obj.text.trim();
  if (typeof obj.output_text === 'string' && obj.output_text.trim()) return obj.output_text.trim();
  return '';
}

let primary = {};
try { primary = $('02B – MANUSKRIPT NORMALISIEREN').first().json || {}; } catch {}

const candidates = [
  { source: 'CURRENT', text: textOf(current), ok: current.ok },
  { source: 'GEMINI', text: textOf(primary), ok: primary.ok }
].filter(x => x.text && x.text.length >= 50);

candidates.sort((a, b) => b.text.length - a.text.length);
const best = candidates[0];

if (!best) {
  const diag = {
    current: { keys: Object.keys(current), apiError: current.apiError || '', httpStatus: current.httpStatus || null },
    gemini: { keys: Object.keys(primary), apiError: primary.apiError || '', httpStatus: primary.httpStatus || null },
    model: $('00 – EINSTELLUNGEN').first().json.claude_model
  };
  const err = String(primary.apiError || current.apiError || '');
  if (/429|rate|quota|resource_exhausted|spacing/i.test(err)) {
    throw new Error('CLAUDE RATE LIMIT / QUOTA (Manuskript-Schritt): Warte und starte erneut. DIAGNOSE: ' + JSON.stringify(diag));
  }
  if (/401|403|invalid|api.?key|permission|denied/i.test(err)) {
    throw new Error('CLAUDE API-KEY FEHLER (Manuskript-Schritt): claude_api_key in 00 – EINSTELLUNGEN prüfen. DIAGNOSE: ' + JSON.stringify(diag));
  }
  throw new Error('PRODUKTION NICHT ERZEUGT: Gemini lieferte keinen verwertbaren Text. DIAGNOSE: ' + JSON.stringify(diag));
}

const manuscript = best.text;
const wc = manuscript.split(/\s+/).filter(Boolean).length;
const pageCount = (manuscript.match(/^##\s*Seite\s+\d+/gmi) || []).length;
const chapterCount = (manuscript.match(/^##\s+/gmi) || []).length;
const visual = d.produktionsmodus === 'VISUELL';

const prompt = visual
  ? `Du bist Qualitätsprüfer für ${d.buchart}. Prüfe die komplette Seiten-/Produktionsvorlage.
Suche nach doppelten Motiven, ungeeigneter Schwierigkeit, unklaren Bildprompts,
Druckproblemen, fehlenden Seiten, Logikfehlern und schwachen Verkaufsmerkmalen.
Liefere ausschließlich einen priorisierten Prüfbericht.

VORLAGE:
${manuscript}`
  : `Du bist ein erfahrener deutscher Buchlektor. Prüfe das vollständige Manuskript gründlich auf
Logik, Aufbau, Wiederholungen, Stil, Lesbarkeit, sachliche Risiken und KI-Floskeln.
Liefere ausschließlich einen priorisierten Lektoratsbericht.

MANUSKRIPT (${wc} Wörter):
${manuscript}`;

return [{
  json: {
    manuscript,
    manuscriptSource: best.source,
    manuscriptWordCount: wc,
    pageCount,
    chapterCount,
    produktionsmodus: d.produktionsmodus,
    requestBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { maxOutputTokens: 14000 }
    }
  }
}];

const r = $json || {};
const asText = v => {
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join('\n');
  if (v && typeof v === 'object') return asText(v.text ?? v.content ?? v.output_text ?? '');
  return '';
};
const candidates = [
  r.content,  // Claude/Anthropic: content: [{ type: 'text', text: '...' }]
  r.choices?.[0]?.message?.content,
  r.choices?.[0]?.text,
  r.candidates?.[0]?.content?.parts,
  r.candidates?.[0]?.output,
  r.output_text,
  r.output?.[0]?.content,
  r.response,
  r.data?.choices?.[0]?.message?.content,
  r.data?.candidates?.[0]?.content?.parts
];
const text = candidates.map(asText).find(v => String(v || '').trim().length >= 20) || '';
const response = String(text).replace(/^\s*```(?:markdown|text)?\s*/i,'').replace(/\s*```\s*$/,'').trim();
return [{json:{ok:response.length >= 20,response,provider:'Claude',error:response ? '' : JSON.stringify(r.error || r)}}];

const input = $json || {};
let d = {};
try { d = $('02 – BUCHART ERKENNEN').first().json || {}; } catch (e) { d = input; }

let manuscript = '';

// 1) Normalfall: Manuskript, das "03 – LEKTORAT BODY" selbst verwendet hat.
try {
  const m = String($('03 – LEKTORAT BODY').first().json.manuscript || '').trim();
  if (m) manuscript = m;
} catch (e) {}

// 2) Fallback: das ORIGINAL-Manuskript direkt aus der Normalisierung nach dem
//    Schreib-Schritt holen (unabhängig davon, ob das Lektorat lief/erfolgreich war
//    oder die Node-Referenz oben aus Verkettungsgründen nicht auflösbar war).
if (!manuscript) {
  try {
    const m = String($('02B – MANUSKRIPT NORMALISIEREN').first().json.response || '').trim();
    if (m) manuscript = m;
  } catch (e) {}
}

// 3) Letzter Fallback: irgendetwas Brauchbares im aktuellen Item.
if (!manuscript) {
  manuscript = String(input.manuscript || input.response || input.buch_de || '').trim();
}

if (!manuscript) {
  const diag = {};
  try { diag.lektoratBodyKeys = Object.keys($('03 – LEKTORAT BODY').first().json || {}); } catch (e) { diag.lektoratBodyError = String(e && e.message || e); }
  try { diag.manuskriptNormalisiertKeys = Object.keys($('02B – MANUSKRIPT NORMALISIEREN').first().json || {}); } catch (e) { diag.manuskriptNormalisiertError = String(e && e.message || e); }
  diag.aktuellesItemKeys = Object.keys(input);
  throw new Error('Keine Produktionsfassung für die Endfassung vorhanden. DIAGNOSE: ' + JSON.stringify(diag));
}

let critique = String(input.response || '').trim();
if (!critique || critique === manuscript) critique = 'Prüfe die Fassung auf Qualität, Vollständigkeit und Fehler.';

const visual = d.produktionsmodus === 'VISUELL';
const lengthHint = 'LÄNGE PFLICHT: Mindestens 8000 Wörter. Kein Kurztext. Alle Kapitel vollständig. Keine Zusammenfassung.';

const prompt = visual
  ? `Du bist Endredakteur für ${d.buchart || 'ein visuelles Buch'}.
Erstelle die vollständige finale Produktionsvorlage.
${lengthHint}
Pflicht: jede Seite mit "## Seite X", keine Platzhalter, keine doppelten Motive.
Gib nur die Vorlage aus.

PRÜFBERICHT:
${critique}

VORLAGE:
${manuscript}`
  : `Du bist Endredakteur.
Schreibe die endgültige Buchfassung.
${lengthHint}
Keine KI-Floskeln, keine erfundenen Quellen.
Gib nur den Buchtext aus.

LEKTORAT:
${critique}

MANUSKRIPT:
${manuscript}`;

return [{
  json: {
    ...input,
    produktionsmodus: d.produktionsmodus,
    requestBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }]
    },
    hoerspiel_prompt: prompt
  }
}];

const r = $json || {};
const asText = v => {
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join('\n');
  if (v && typeof v === 'object') return asText(v.text ?? v.content ?? v.output_text ?? '');
  return '';
};
const candidates = [
  r.content,  // Claude/Anthropic: content: [{ type: 'text', text: '...' }]
  r.choices?.[0]?.message?.content,
  r.choices?.[0]?.text,
  r.candidates?.[0]?.content?.parts,
  r.candidates?.[0]?.output,
  r.output_text,
  r.output?.[0]?.content,
  r.response,
  r.data?.choices?.[0]?.message?.content,
  r.data?.candidates?.[0]?.content?.parts
];
const text = candidates.map(asText).find(v => String(v || '').trim().length >= 500) || '';
const response = String(text).replace(/^\s*```(?:markdown|text)?\s*/i,'').replace(/\s*```\s*$/,'').trim();
return [{json:{ok:response.length >= 500,response,provider:'Claude',error:response ? '' : JSON.stringify(r.error || r)}}];

function alsText(wert) {
  if (typeof wert !== 'string') return '';

  const text = wert.trim();

  if (
    !text ||
    text === '[object Object]' ||
    text === 'undefined' ||
    text === 'null'
  ) {
    return '';
  }

  return text;
}

function sucheText(json) {
  const j = json ?? {};
  const body = j.body ?? {};

  const kandidaten = [
    j.endfassung,
    j.finalText,
    j.final_text,
    j.manuskript,
    j.buchtext,
    j.lektorat,
    j.text,
    j.output_text,
    j.response,
    j.answer,
    j.result,

    j.message?.content,
    j.choices?.[0]?.message?.content,
    j.choices?.[0]?.text,
    j.output?.[0]?.content?.[0]?.text,
    j.candidates?.[0]?.content?.parts?.[0]?.text,
    Array.isArray(j.content) ? j.content[0]?.text : j.content,

    body.endfassung,
    body.finalText,
    body.final_text,
    body.manuskript,
    body.buchtext,
    body.lektorat,
    body.text,
    body.output_text,
    body.response,
    body.answer,
    body.result,

    body.message?.content,
    body.choices?.[0]?.message?.content,
    body.choices?.[0]?.text,
    body.output?.[0]?.content?.[0]?.text,
    body.candidates?.[0]?.content?.parts?.[0]?.text,
    Array.isArray(body.content)
      ? body.content[0]?.text
      : body.content
  ];

  for (const kandidat of kandidaten) {
    const text = alsText(kandidat);
    if (text) return text;
  }

  return '';
}

function leseNode(name) {
  try {
    return $(name).all().map(item => ({
      node: name,
      json: item.json ?? {}
    }));
  } catch (fehler) {
    return [];
  }
}

/*
 * Zuerst alle direkten Eingänge von 05 einsammeln.
 */
let quellen = $input.all().map((item, index) => ({
  node: `Direkter Eingang ${index + 1}`,
  json: item.json ?? {}
}));

/*
 * Danach Primär- und Ersatzfassung direkt aus den vorherigen
 * Nodes holen. Dadurch funktioniert es auch bei Problemen
 * mit Merge-, IF- oder Switch-Verbindungen.
 */
const moeglicheNodes = [
  '04O – ENDFASSUNG MINDESTLÄNGE',
  '04L – ERWEITERUNG 1 PRÜFEN',
  '04I – RECHTSCHREIBUNG PRÜFEN',
  '04F – FALLBACK ENDFASSUNG NORMALISIEREN',
  '04B – ENDFASSUNG NORMALISIEREN',
  '04A – CLAUDE ENDFASSUNG',
  '03F – FALLBACK LEKTORAT NORMALISIEREN',
  '03B – LEKTORAT NORMALISIEREN',
  '02F – FALLBACK MANUSKRIPT NORMALISIEREN',
  '02B – MANUSKRIPT NORMALISIEREN'
]

for (const nodeName of moeglicheNodes) {
  quellen.push(...leseNode(nodeName));
}

const fundstellen = [];

for (const quelle of quellen) {
  const text = sucheText(quelle.json);

  if (text) {
    fundstellen.push({
      node: quelle.node,
      text,
      zeichen: text.length,
      woerter: text.split(/\s+/).filter(Boolean).length,
      json: quelle.json
    });
  }
}

if (fundstellen.length === 0) {
  return [{
    json: {
      status: 'FEHLER',
      fehler: 'Keine Textfassung in den vorherigen Nodes gefunden.',
      gepruefteQuellen: quellen.map(quelle => ({
        node: quelle.node,
        felder: Object.keys(quelle.json ?? {}),
        bodyFelder:
          typeof quelle.json?.body === 'object' &&
          quelle.json.body !== null
            ? Object.keys(quelle.json.body)
            : []
      }))
    }
  }];
}

/*
 * Die längste vorhandene Fassung verwenden.
 */
fundstellen.sort((a, b) => b.zeichen - a.zeichen);

const besteFassung = fundstellen[0];
const basis = besteFassung.json;

let parsedTitle = '';
const h1 = besteFassung.text.match(/^#\s+(.+)$/m);
if (h1) parsedTitle = h1[1].trim();
const titel = alsText(basis.titel) || alsText(basis.title) || alsText(basis.buchtitel) || parsedTitle || 'Buch ohne Titel';

const autor =
  alsText(basis.autor) ||
  alsText(basis.author) ||
  'Mitch';

const meta = $('00A – KDP FORMATKATALOG').first().json;
const detect = $('02 – BUCHART ERKENNEN').first().json;
return [{
  json: {
    ...meta,
    ...basis,
    buchart: detect.buchart,
    produktionsmodus: detect.produktionsmodus,
    buchauftragOriginal: meta.buchauftrag || '',
    projektOrdner: String(titel).normalize('NFKD').replace(/[^a-zA-Z0-9äöüÄÖÜß]+/g,'_').replace(/^_+|_+$/g,'').slice(0,70) || 'Buchprojekt',
    ausgabePfad: '/data/firma/Buch Ergebnisse/' + (String(titel).normalize('NFKD').replace(/[^a-zA-Z0-9äöüÄÖÜß]+/g,'_').replace(/^_+|_+$/g,'').slice(0,70) || 'Buchprojekt'),
    buchOrdnerName: String(titel).normalize('NFKD').replace(/[^a-zA-Z0-9äöüÄÖÜß]+/g,'_').replace(/^_+|_+$/g,'').slice(0,70) || 'Buchprojekt',

    status: 'OK',
    titel,
    buchtitel: titel,
    autor,

    endfassung: besteFassung.text,
    manuskript: besteFassung.text,
    buchtext: besteFassung.text,
    buch_de: besteFassung.text,
    text: besteFassung.text,

    verwendeteQuelle: besteFassung.node,
    gefundeneFassungen: fundstellen.length,
    zeichen: besteFassung.zeichen,
    woerter: besteFassung.woerter
  }
}];

const s = $('00 – EINSTELLUNGEN').first().json;
const auftrag = String(s.buchauftrag || '').toLowerCase();

