  if (value && typeof value === 'object') {
    return asText(
      value.text ??
      value.content ??
      value.output_text ??
      value.response ??
      value.answer ??
      value.result ??
      value.generated_text ??
      value.message?.content ??
      value.candidates?.[0]?.content?.parts ??
      value.choices?.[0]?.message?.content ??
      ''
    );
  }
  return '';
}

