const groessenKreuzwort = { leicht: 15, mittel: 17, schwer: 19 };
const groessenSuchsel = { leicht: 12, mittel: 14, schwer: 16 };
const labyrinthGroessen = { leicht: [10, 10], mittel: [14, 14], schwer: [18, 18] };

const raetselSeiten = [];
const warnungen = [];

for (const seite of seitenplan) {
  try {
    if (seite.typ === 'sudoku') {
      const { puzzle, solution } = sudokuGenerate(schwierigkeit);
      raetselSeiten.push({ index: seite.index, typ: 'sudoku', titel: `Sudoku – Seite ${seite.index}`, daten: { puzzle, solution } });
    } else if (seite.typ === 'labyrinth') {
      const [cols, rows] = labyrinthGroessen[schwierigkeit] || labyrinthGroessen.mittel;
      const laby = labyrinthGenerieren(cols, rows);
      raetselSeiten.push({ index: seite.index, typ: 'labyrinth', titel: `Labyrinth – Seite ${seite.index}`, daten: laby });
    } else if (seite.typ === 'kreuzwort') {
      const woerter = wortlisten[seite.index] || [];
      const kw = kreuzwortGenerieren(woerter, { groesse: groessenKreuzwort[schwierigkeit] || 17 });
      if (kw.platzierteWoerter < 5) warnungen.push(`Seite ${seite.index}: nur ${kw.platzierteWoerter} Kreuzwort-Wörter platziert`);
      raetselSeiten.push({ index: seite.index, typ: 'kreuzwort', titel: `Kreuzworträtsel – Seite ${seite.index}`, daten: kw });
    } else if (seite.typ === 'suchsel') {
      const woerter = (wortlisten[seite.index] || []).map(w => w.wort);
      const ss = suchselGenerieren(woerter, { groesse: groessenSuchsel[schwierigkeit] || 14 });
      if (ss.platzierteWoerter < 6) warnungen.push(`Seite ${seite.index}: nur ${ss.platzierteWoerter} Suchsel-Wörter platziert`);
      raetselSeiten.push({ index: seite.index, typ: 'suchsel', titel: `Wortsuche – Seite ${seite.index}`, daten: ss });
    }
  } catch (e) {
    warnungen.push(`Seite ${seite.index} (${seite.typ}) konnte nicht erzeugt werden: ${e.message}`);
  }
}

if (!raetselSeiten.length) {
  throw new Error('RÄTSELBUCH: Es konnte keine einzige Rätselseite erzeugt werden. Einstellungen (raetsel_seiten_anzahl, raetsel_schwierigkeit) prüfen.');
}

return [{ json: { raetselSeiten, warnungen, raetselSeitenAnzahl: raetselSeiten.length, schwierigkeit, wortlistenFallbackUsed: x.wortlistenFallbackUsed || false } }];

