    }
  }
  for (let r = 0; r < d.groesse; r++) {
    h += '<tr>';
    for (let c = 0; c < d.groesse; c++) {
      const key = `${r},${c}`;
      h += `<td class="${markiert.has(key) ? 'gefunden' : ''}">${esc(d.grid[r][c])}</td>`;
    }
    h += '</tr>';
  }
  h += '</table>';
  if (!loesung) {
    h += '<div class="wortliste">' + d.platziert.map(w => `<span>${esc(w.wort)}</span>`).join(' · ') + '</div>';
  }
  return h;
}

function labyrinthSeiteHtml(seite, loesung) {
  const d = seite.daten;
  const zg = 18;
  const breite = d.cols * zg, hoehe = d.rows * zg;
  let linien = '';
  for (let r = 0; r < d.rows; r++) {
    for (let c = 0; c < d.cols; c++) {
      const zelle = d.zellen[r][c];
      const x0 = c * zg, y0 = r * zg, x1 = x0 + zg, y1 = y0 + zg;
      if (zelle.N) linien += `<line x1="${x0}" y1="${y0}" x2="${x1}" y2="${y0}"/>`;
      if (zelle.W) linien += `<line x1="${x0}" y1="${y0}" x2="${x0}" y2="${y1}"/>`;
      if (r === d.rows - 1 && zelle.S) linien += `<line x1="${x0}" y1="${y1}" x2="${x1}" y2="${y1}"/>`;
      if (c === d.cols - 1 && zelle.E) linien += `<line x1="${x1}" y1="${y0}" x2="${x1}" y2="${y1}"/>`;
    }
  }
  let pfad = '';
  if (loesung) {
    const pts = d.pfad.map(([r, c]) => `${c * zg + zg / 2},${r * zg + zg / 2}`).join(' ');
    pfad = `<polyline points="${pts}" fill="none" stroke="red" stroke-width="3"/>`;
  }
  return `<h2>${esc(seite.titel)}</h2><svg viewBox="0 0 ${breite} ${hoehe}" class="labyrinth"><rect x="0" y="0" width="${breite}" height="${hoehe}" fill="white" stroke="black" stroke-width="3"/>${linien}${pfad}</svg>`;
}

function seiteRendern(seite, loesung) {
